981	/* ══════════════════════════════════════════════════════════════════════
982	   Property hero-morph transition  (View Transitions API + stagger CSS)
983	   ══════════════════════════════════════════════════════════════════════
984	
985	   How it works:
986	   1. Both the Tenant Directory hero and Tenant Profile hero carry the class
987	      .pt-hero, giving them view-transition-name: property-hero.
988	   2. document.startViewTransition() captures old + new DOM snapshots.
989	   3. The browser automatically interpolates position, size, and border-radius
990	      between the two hero cards.  We only animate the content cross-fade.
991	   4. The root (everything outside the hero) fades + scales out; the new
992	      page's secondary elements self-animate with .pt-bounce / .pt-slide-top.
993	   ═══════════════════════════════════════════════════════════════════════ */
994	
995	/* Tag the morphing element on both pages */
996	.pt-hero {
997	  view-transition-name: property-hero;
998	}
999	
1000	/* ── Hero: content cross-fade inside the morphing card ──────────────── */
1001	::view-transition-old(property-hero) {
1002	  animation: 340ms cubic-bezier(0.4, 0, 0.2, 1) both pt-fade-out;
1003	}
1004	::view-transition-new(property-hero) {
1005	  animation: 500ms cubic-bezier(0.34, 1.56, 0.64, 1) both pt-fade-in;
1006	}
1007	@keyframes pt-fade-out { to   { opacity: 0; } }
1008	@keyframes pt-fade-in  { from { opacity: 0; } }
1009	
1010	/* ── Root (non-hero): old page exits, new page appears bare ─────────── */
1011	::view-transition-old(root) {
1012	  animation: 210ms cubic-bezier(0.4, 0, 1, 1) both pt-root-out;
1013	}
1014	::view-transition-new(root) {
1015	  /* New page appears immediately; individual elements animate themselves */
1016	  animation: 1ms linear both;
1017	}
1018	@keyframes pt-root-out {
1019	  to { opacity: 0; transform: scale(0.97) translateY(-6px); }
1020	}
1021	
1022	/* ── Bounce pop in — used for profile secondary elements ─────────────── */
1023	@keyframes bouncePopIn {
1024	  0%   { opacity: 0; transform: translateY(30px) scale(0.86); }
1025	  55%  { opacity: 1; transform: translateY(-7px) scale(1.045); }
1026	  74%  { transform: translateY(3px) scale(0.983); }
1027	  88%  { transform: translateY(-1.5px) scale(1.007); }
1028	  100% { opacity: 1; transform: translateY(0) scale(1); }
1029	}
1030	
1031	/* ── Slide pop from above — used for the top bar ─────────────────────── */
1032	@keyframes slideInFromTop {
1033	  from { opacity: 0; transform: translateY(-18px) scale(0.96); }
1034	  to   { opacity: 1; transform: translateY(0)     scale(1);    }
1035	}
1036	
1037	.pt-bounce {
1038	  opacity: 0;
1039	  animation: bouncePopIn 0.52s cubic-bezier(0.34, 1.56, 0.64, 1) both;
1040	  animation-delay: var(--pt-d, 0ms);
1041	}
1042	
1043	.pt-slide-top {
1044	  opacity: 0;
1045	  animation: slideInFromTop 0.30s cubic-bezier(0.22, 1, 0.36, 1) both;
1046	  animation-delay: var(--pt-d, 0ms);
1047	}
1048	
1049	/* ── Respect prefers-reduced-motion ─────────────────────────────────── */
1050	@media (prefers-reduced-motion: reduce) {
1051	  ::view-transition-old(property-hero),
1052	  ::view-transition-new(property-hero),
1053	  ::view-transition-old(root),
1054	  ::view-transition-new(root) {
1055	    animation-duration: 0.01ms !important;
1056	  }
1057	  .pt-bounce,
1058	  .pt-slide-top {
1059	    animation: none !important;
1060	    opacity: 1 !important;
1061	  }
1062	}
1063	
1064	/* ── Native Apple Pay button ─────────────────────────────────────────── */
1065	.apple-pay-btn {
1066	  -webkit-appearance: -apple-pay-button;
1067	  -apple-pay-button-type: pay;
1068	  -apple-pay-button-style: black;
1069	  display: block;
1070	  width: 100%;
1071	  height: 52px;
1072	  min-height: 44px;
1073	  border: none;
1074	  border-radius: 18px;
1075	  cursor: pointer;
1076	  margin-bottom: 10px;
1077	}
