cat > /tmp/shot.mjs <<'EOF'
import { chromium } from 'playwright';
const file = 'file://' + process.cwd() + '/tapt-landing.html';
const b = await chromium.launch();
for (const [name, vw, vh] of [['desktop',1440,900],['mobile',390,844]]) {
  const p = await b.newPage({ viewport: { width: vw, height: vh }, deviceScaleFactor: 2 });
  await p.goto(file, { waitUntil: 'networkidle' });
  await p.waitForTimeout(1600); // let reveal + fonts settle
  await p.screenshot({ path: `/tmp/tapt-${name}-top.png` });
  await p.evaluate(() => document.querySelector('#shift').scrollIntoView());
  await p.waitForTimeout(600);
  await p.screenshot({ path: `/tmp/tapt-${name}-shift.png` });
  console.log(name, 'title:', await p.title());
  await p.close();
}
await b.close();
EOF
node /tmp/shot.mjs

